CREATE OR REPLACE FUNCTION public.initialize_occurrence_sla() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.accounts; t public.sla_targets; BEGIN SELECT * INTO STRICT a FROM public.accounts WHERE id=NEW.account_id AND active; SELECT * INTO STRICT t FROM public.sla_targets WHERE policy_id=a.sla_policy_id AND severity=public.calculate_severity(NEW.impact,NEW.urgency); NEW.created_at:=now(); NEW.status:='registered'; NEW.severity:=t.severity; NEW.resolution_started_at:=NEW.created_at; NEW.first_response_due_at:=public.add_business_minutes(a.calendar_id,NEW.created_at,t.first_response_minutes); NEW.resolution_due_at:=public.add_business_minutes(a.calendar_id,NEW.created_at,t.resolution_minutes); NEW.first_response_at:=NULL; NEW.first_response_breached:=false; NEW.resolution_breached:=false; NEW.paused_business_minutes:=0; NEW.paused_since:=NULL; NEW.paused_from_status:=NULL; NEW.reopen_count:=0; NEW.solution_proposed_at:=NULL; NEW.closed_at:=NULL; NEW.classification_confirmed_at:=NULL; NEW.classification_confirmed_by:=NULL; NEW.assignee_id:=NULL; NEW.next_update_due_at:=NULL; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.capture_sla_cycle() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target_minutes integer; cycle_breached boolean; BEGIN SELECT t.resolution_minutes INTO STRICT target_minutes FROM public.accounts a JOIN public.sla_targets t ON t.policy_id=a.sla_policy_id AND t.severity=NEW.severity WHERE a.id=NEW.account_id; cycle_breached:=CASE WHEN NEW.status='awaiting_customer' THEN NEW.paused_since>NEW.resolution_due_at WHEN NEW.status IN ('solution_proposed','closed_resolved','closed_no_evaluation') THEN NEW.solution_proposed_at>NEW.resolution_due_at WHEN NEW.status='closed_unfounded' THEN NEW.closed_at>NEW.resolution_due_at ELSE now()>NEW.resolution_due_at END; IF TG_OP='UPDATE' AND NEW.reopen_count>OLD.reopen_count THEN UPDATE public.occurrence_sla_cycles SET ended_at=coalesce(ended_at,now()) WHERE occurrence_id=OLD.id AND cycle=OLD.reopen_count+1; END IF; INSERT INTO public.occurrence_sla_cycles(occurrence_id,cycle,started_at,due_at,solution_proposed_at,ended_at,paused_business_minutes,severity,resolution_minutes,resolution_breached) VALUES(NEW.id,NEW.reopen_count+1,NEW.resolution_started_at,NEW.resolution_due_at,NEW.solution_proposed_at,NEW.closed_at,NEW.paused_business_minutes,NEW.severity,target_minutes,coalesce(cycle_breached,false)) ON CONFLICT(occurrence_id,cycle) DO UPDATE SET due_at=excluded.due_at,solution_proposed_at=excluded.solution_proposed_at,ended_at=excluded.ended_at,paused_business_minutes=excluded.paused_business_minutes,severity=excluded.severity,resolution_minutes=excluded.resolution_minutes,resolution_breached=occurrence_sla_cycles.resolution_breached OR excluded.resolution_breached; RETURN NEW; END $$;